def _opening_balances(ctx: Context) -> dict[tuple[str, str], Decimal]:
    balances: dict[tuple[str, str], Decimal] = {}
    for entity, lines in ctx.inputs.trial_balances.items():
        for line in lines:
            key = (entity, line.local_code)
